mapper.select:
update prj_project_approval
set data_class = #{dataClass}
where project_id = #{projectId}
  and data_class = 'CHANGE'

SELECT t.*, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) finance_amount, ( SELECT q.lease_term FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) lease_term, ( SELECT q.int_rate FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) int_rate, ( SELECT v.meaning FROM prj_quotation q, sys_code_value_b_v v WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id AND q.BUSINESS_TYPE = v.CODE_VALUE AND v. CODE = 'HLS200.LEASING_PRODUCT_DETAIL' ) business_type_n, (select b.bp_name from prj_project p,hls_bp_master b where p.tenant_id = b.bp_id and p.project_id = t.project_id )tenant_id_n, (select b.company_short_name from prj_project p,fnd_company b where p.company_id = b.company_id and p.project_id = t.project_id )lessor_name FROM prj_project_approval t
1=1 and t.data_class = (case (select h.duration_status from hls_duration_hd h where h.hd_id = #{hdId}) when 'APPROVING' then 'CHANGE' when 'CANCEL' then 'CANCEL' else 'NORMAL' end )
and t.project_id = #{projectId}

SELECT t.*, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) finance_amount, ( SELECT q.lease_term FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) lease_term, ( SELECT q.int_rate FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) int_rate, ( SELECT v.meaning FROM prj_quotation q, sys_code_value_b_v v WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id AND q.BUSINESS_TYPE = v.CODE_VALUE AND v. CODE = 'HLS200.LEASING_PRODUCT_DETAIL' ) business_type_n, (select b.bp_name from prj_project p,hls_bp_master b where p.tenant_id = b.bp_id and p.project_id = t.project_id )tenant_id_n, (select b.company_short_name from prj_project p,fnd_company b where p.company_id = b.company_id and p.project_id = t.project_id )lessor_name FROM prj_project_approval t
1=1 and t.data_class = 'NORMAL'
and t.project_id = #{projectId}
and nvl(t.approval_type,'NORMAL')=#{approvalType}

SELECT t.*, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) finance_amount, ( SELECT q.lease_term FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) lease_term, ( SELECT concat(q.int_rate * 100, '%') FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id ) int_rate, ( SELECT v.meaning FROM prj_quotation q, sys_code_value_b_v v WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'PRJ_PROJECT_INVEST' AND q.SOURCE_DOCUMENT_ID = t.project_id AND q.BUSINESS_TYPE = v.CODE_VALUE AND v. CODE = 'HLS200.LEASING_PRODUCT_DETAIL' ) business_type_n, (select b.bp_name from prj_project p,hls_bp_master b where p.tenant_id = b.bp_id and p.project_id = t.project_id )tenant_id_n, (select b.company_short_name from prj_project p,fnd_company b where p.company_id = b.company_id and p.project_id = t.project_id )lessor_name FROM prj_project_approval t
1=1 and t.data_class = 'CHANGE'
and t.project_id = #{projectId}

SELECT t.*, ( SELECT q.finance_amount FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'VIRTUAL_CON' AND q.SOURCE_DOCUMENT_ID = t.project_id ) finance_amount, ( SELECT q.lease_term FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'VIRTUAL_CON' AND q.SOURCE_DOCUMENT_ID = t.project_id ) lease_term, ( SELECT concat(q.int_rate * 100, '%') FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'VIRTUAL_CON' AND q.SOURCE_DOCUMENT_ID = t.project_id ) int_rate, ( SELECT v.meaning FROM prj_quotation q, sys_code_value_b_v v WHERE q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' and q.data_class = 'VIRTUAL_CON' AND q.SOURCE_DOCUMENT_ID = t.project_id AND q.BUSINESS_TYPE = v.CODE_VALUE AND v. CODE = 'HLS200.LEASING_PRODUCT_DETAIL' ) business_type_n, (select b.bp_name from prj_project p,hls_bp_master b where p.tenant_id = b.bp_id and p.project_id = t.project_id )tenant_id_n, (select b.company_short_name from prj_project p,fnd_company b where p.company_id = b.company_id and p.project_id = t.project_id )lessor_name FROM prj_project_approval t
1=1 and t.data_class = 'NORMAL' and t.APPROVAL_TYPE = 'NORMAL'
and t.project_id = #{projectId}

mapper.update:
UPDATE
    prj_project_approval
SET
    approval_result = #{approvalResult}
WHERE
    approval_id = #{approvalId}
